customCSS:
.t, .history { color: #928374; }
.join { color: #79740e; }
.part, .quit { color: #928374; }
.kick, .error { color: #9d0006; }
.notice { color: #b57614; }
.action { color: #8f3f71; }
.mode, .nick, .topic, .server { color: #427b58; }
.highlight { color: #3c3836; background-color: #bdae93; border-left: 3px solid #8f3f71; padding-left: 8px; }
.reply { color: #928374; border-left: 2px solid #076678; padding-left: 6px; }
.oper { color: #fbf1c7; background-color: #b57614; }
.reactions { color: #076678; background-color: #ebdbb2; }
.card { background-color: #ebdbb2; border-color: #928374; }
.card-title { color: #076678; }
.card-desc { color: #928374; }
.daychange { color: #928374; border-color: #ebdbb2; }
